    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("reftable hash id ")?;
        fmt::Display::fmt(&self.0, f)?;
        f.write_str(" is not named by reftable-basics.h")
