/// `parser`'s fields through the safe handles.
fn rust_fields(parser: ParserRef<'_>, data: &[u8]) -> Fields {
    Fields {
        parser_type: parser.parser_type_raw(),
        http_major: parser.http_major(),
        http_minor: parser.http_minor(),
