pub fn error_offset(&self, data: &[u8]) -> Option<usize> {
    let pos = get!(self, error_pos);
    if pos.is_null() {
        return None;
    }
    let offset = pos.addr().checked_sub(data.as_ptr().addr())?;
    (offset <= data.len()).then_some(offset)
}

